-- Добавление дополнительных тестовых данных для AQUM
USE aqum_db;

-- Больше постов от учителей
INSERT INTO posts (teacher_id, title, content, tags, likes_count, comments_count, views_count, created_at) VALUES
(3, 'Как быстро выучить 100 английских слов', 'Делюсь своей методикой запоминания слов:\n\n1️⃣ Интервальное повторение\n2️⃣ Контекстное изучение\n3️⃣ Ассоциации и визуализация\n4️⃣ Практика в диалогах\n\nЗа неделю вы сможете запомнить 100+ слов! 💪', 'english,learning,vocabulary', 189, 34, 1456, DATE_SUB(NOW(), INTERVAL 2 DAY)),

(4, 'Лайфхак: Таблица умножения за 1 день', 'Да, это возможно! Научу вашего ребёнка таблице умножения всего за один день.\n\nМетодика построена на визуальной памяти и игровой форме.\n\nПроверено на 200+ учениках! ✨', 'math,kids,tips', 345, 67, 2890, DATE_SUB(NOW(), INTERVAL 3 DAY)),

(5, 'Figma vs Adobe XD: что выбрать в 2024?', 'Сравнил два популярных инструмента для UI/UX дизайна:\n\n**Figma:**\n✅ Работает в браузере\n✅ Мощная коллаборация\n✅ Бесплатный тариф\n\n**Adobe XD:**\n✅ Интеграция с Adobe\n✅ Быстрая работа\n\nМой выбор - Figma! А ваш? 🎨', 'design,tools,figma', 234, 89, 3210, DATE_SUB(NOW(), INTERVAL 1 DAY)),

(6, 'Первый Python проект: Телеграм-бот за 30 минут', 'Сегодня создадим простого бота для Telegram!\n\nЧто понадобится:\n- Python 3.8+\n- Библиотека python-telegram-bot\n- 30 минут времени\n\nПолный код в комментариях! 🚀', 'programming,python,telegram', 456, 123, 4567, DATE_SUB(NOW(), INTERVAL 5 HOUR)),

(7, 'Топ-5 упражнений для развития голоса', 'Хотите петь красиво? Начните с этих упражнений:\n\n1. Дыхательная гимнастика\n2. Распевки на гласные\n3. Артикуляционная гимнастика\n4. Упражнения на дикцию\n5. Работа с резонаторами\n\nДелайте каждый день по 15 минут! 🎵', 'music,voice,exercises', 178, 45, 1234, DATE_SUB(NOW(), INTERVAL 1 DAY)),

(3, 'IELTS Speaking: как получить 7+', 'Секреты успешной сдачи Speaking части экзамена IELTS:\n\n✅ Развёрнутые ответы (не да/нет)\n✅ Используйте связующие слова\n✅ Приводите примеры\n✅ Не бойтесь ошибок\n\nГотовлю к IELTS уже 5 лет, средний балл моих студентов - 7.5! 🎯', 'english,ielts,exam', 267, 56, 2345, DATE_SUB(NOW(), INTERVAL 6 HOUR)),

(4, 'ЕГЭ по математике: разбор сложных заданий', 'Сегодня разберём задание №18 (параметры).\n\nЭто одно из самых сложных заданий, но есть алгоритм решения!\n\n📊 Шаг 1: Анализ условия\n📊 Шаг 2: Построение графика\n📊 Шаг 3: Нахождение пересечений\n\nВидео с подробным разбором - в профиле!', 'math,ege,exam', 389, 78, 3456, DATE_SUB(NOW(), INTERVAL 4 HOUR)),

(5, 'Цветовая психология в дизайне', 'Как цвета влияют на восприятие продукта:\n\n🔴 Красный - энергия, действие\n🔵 Синий - доверие, стабильность\n🟢 Зелёный - природа, рост\n🟣 Фиолетовый - роскошь, креативность\n🟡 Жёлтый - оптимизм, тепло\n\nВыбирайте цвета осознанно! 🎨', 'design,colors,psychology', 312, 67, 2789, DATE_SUB(NOW(), INTERVAL 8 HOUR)),

(6, 'JavaScript: async/await vs Promises', 'Многие путают эти концепции. Давайте разберёмся!\n\n**Promises:**\n```js\nfetch(url)\n  .then(response => response.json())\n  .then(data => console.log(data));\n```\n\n**Async/Await:**\n```js\nconst response = await fetch(url);\nconst data = await response.json();\nconsole.log(data);\n```\n\nAsync/await - это синтаксический сахар над промисами! 🍬', 'programming,javascript,async', 423, 91, 3890, DATE_SUB(NOW(), INTERVAL 3 HOUR)),

(7, 'Разминка для вокалистов: 10-минутный комплекс', 'Перед каждым занятием важно разогреть голосовые связки!\n\nМой быстрый комплекс:\n- 3 мин: дыхательные упражнения\n- 3 мин: распевки на «ма-мэ-ми-мо-му»\n- 2 мин: скороговорки\n- 2 мин: работа с диапазоном\n\nНикогда не пойте без разминки! 🎤', 'music,vocal,warmup', 145, 32, 987, DATE_SUB(NOW(), INTERVAL 2 HOUR));

